    m::Vector{Float64}
    p::Vector{Float64}
    ε::Vector{Float64}
    ν::Vector{Float64}
    cs::Vector{Float64}
    cs_prime::Vector{Float64}
    cs_prime_prime::Vector{Float64}
    r::Vector{Float64}
    η::Float64
    ζ::Float64
    τε::Float64
    τP::Float64
    τQ::Float64
    L::Float64
    h::Float64
    N::Int64
    
    # Derived fields
    A1::Vector{Float64}
    A2::Vector{Float64}
    A3::Vector{Float64}
    A4::Vector{Float64}
    A5::Vector{Float64}
    A6::Vector{Float64}
    A7::Vector{Float64}
    A8::Vector{Float64}
