    # Inner Constructor
    function CNSystem(m::Vector{Float64}, p::Vector{Float64}, ε::Vector{Float64}, ν::Vector{Float64}, cs::Vector{Float64}, cs_prime::Vector{Float64}, cs_prime_prime::Vector{Float64}, r::Vector{Float64}, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64, h::Float64, N::Int64)
        if N != length(m)
            throw(ArgumentError("Length of m must be equal to N"))
        end

        A1_calc = zeros(Float64, N)
        A2_calc = zeros(Float64, N)
        A3_calc = zeros(Float64, N)
        A4_calc = zeros(Float64, N)
        A5_calc = zeros(Float64, N)
        A6_calc = zeros(Float64, N)
        A7_calc = zeros(Float64, N)
        A8_calc = zeros(Float64, N)
        A9_calc = zeros(Float64, N)
        A10_calc = zeros(Float64, N)
        A11_calc = zeros(Float64, N)
        A12_calc = zeros(Float64, N)
        A13_calc = zeros(Float64, N)
        A14_calc = zeros(Float64, N)
        B1_calc = zeros(Float64, N)
        B2_calc = zeros(Float64, N)
        B3_calc = zeros(Float64, N)
        B4_calc = zeros(Float64, N)
        B5_calc = zeros(Float64, N)
        B6_calc = zeros(Float64, N)
        B7_calc = zeros(Float64, N)
        B8_calc = zeros(Float64, N)
        B9_calc = zeros(Float64, N)
        B10_calc = zeros(Float64, N)
        B11_calc = zeros(Float64, N)
        B12_calc = zeros(Float64, N)
        B13_calc = zeros(Float64, N)
        B14_calc = zeros(Float64, N)
        C1_calc = zeros(Float64, N)
        C2_calc = zeros(Float64, N)
        C3_calc = zeros(Float64, N)
        C4_calc = zeros(Float64, N)
        C5_calc = zeros(Float64, N)
        C6_calc = zeros(Float64, N)
        C7_calc = zeros(Float64, N)
        C8_calc = zeros(Float64, N)

        A1_calc[1] = NaN;
        A2_calc[1] = NaN;
        A3_calc[1] = NaN;
        A4_calc[1] = NaN;
        A5_calc[1] = NaN;
        A6_calc[1] = NaN;
        A7_calc[1] = NaN;
        A8_calc[1] = NaN;
        A9_calc[1] = NaN;
        A10_calc[1] = NaN;
        A11_calc[1] = NaN;
        A12_calc[1] = NaN;
        A13_calc[1] = NaN;
        A14_calc[1] = NaN;
        B1_calc[1] = NaN;
        B2_calc[1] = NaN;
        B3_calc[1] = NaN;
        B4_calc[1] = NaN;
        B5_calc[1] = NaN;
        B6_calc[1] = NaN;
        B7_calc[1] = NaN;
        B8_calc[1] = NaN;
        B9_calc[1] = NaN;
        B10_calc[1] = NaN;
        B11_calc[1] = NaN;
        B12_calc[1] = NaN;
        B13_calc[1] = NaN;
        B14_calc[1] = NaN;
        C1_calc[1] = NaN;
        C2_calc[1] = NaN;
        C3_calc[1] = NaN;
        C4_calc[1] = NaN;
        C5_calc[1] = NaN;
        C6_calc[1] = NaN;
        C7_calc[1] = NaN;
        C8_calc[1] = NaN;

        @inbounds @Threads.threads for i = 2:N
            A1_calc[i] = A1(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A2_calc[i] = A2(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A3_calc[i] = A3(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A4_calc[i] = A4(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A5_calc[i] = A5(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A6_calc[i] = A6(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A7_calc[i] = A7(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A8_calc[i] = A8(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A9_calc[i] = A9(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A10_calc[i] = A10(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A11_calc[i] = A11(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A12_calc[i] = A12(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A13_calc[i] = A13(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            A14_calc[i] = A14(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B1_calc[i] = B1(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B2_calc[i] = B2(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B3_calc[i] = B3(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B4_calc[i] = B4(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B5_calc[i] = B5(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B6_calc[i] = B6(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B7_calc[i] = B7(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B8_calc[i] = B8(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B9_calc[i] = B9(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B10_calc[i] = B10(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B11_calc[i] = B11(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B12_calc[i] = B12(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B13_calc[i] = B13(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            B14_calc[i] = B14(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            C1_calc[i] = C1(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            C2_calc[i] = C2(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            C3_calc[i] = C3(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            C4_calc[i] = C4(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            C5_calc[i] = C5(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            C6_calc[i] = C6(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            C7_calc[i] = C7(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
            C8_calc[i] = C8(m[i], p[i], ε[i], ν[i], cs[i], cs_prime[i], cs_prime_prime[i], r[i], η, ζ, τε, τP, τQ, L)
        end

        D1_calc = D1(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        D2_calc = D2(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        D3_calc = D3(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        D4_calc = D4(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)

        E1_calc = E1(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        E2_calc = E2(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        E3_calc = E3(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        E4_calc = E4(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        E5_calc = E5(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        E6_calc = E6(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)

        F1_calc = F1(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        F2_calc = F2(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        F3_calc = F3(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)

        G1_calc = G1(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        G2_calc = G2(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)
        G3_calc = G3(p[1], ε[1], ν[1], cs[1], cs_prime[1], cs_prime_prime[1], η, ζ, τε, τP, τQ, L)

        
        # 2. Call 'new' with all fields in the order they were defined
        new(m, p, ε, ν, cs, cs_prime, cs_prime_prime, r, η, ζ, τε, τP, τQ, L, h, N, 
            A1_calc, A2_calc, A3_calc, A4_calc, A5_calc, A6_calc, A7_calc, A8_calc, A9_calc, A10_calc, A11_calc, A12_calc, A13_calc, A14_calc,
            B1_calc, B2_calc, B3_calc, B4_calc, B5_calc, B6_calc, B7_calc, B8_calc, B9_calc, B10_calc, B11_calc, B12_calc, B13_calc, B14_calc,
            C1_calc, C2_calc, C3_calc, C4_calc, C5_calc, C6_calc, C7_calc, C8_calc, D1_calc, D2_calc, D3_calc, D4_calc, E1_calc, E2_calc, E3_calc, E4_calc, E5_calc, E6_calc, F1_calc, F2_calc, F3_calc, G1_calc, G2_calc, G3_calc)
    end
end

A1(m::Float64, p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime::Float64, cs_prime_prime::Float64, r::Float64, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64)::Float64 =(4*L^2*π*(3*ζ + 4*η)*τQ*(p + ε)^2*(-2*m^2*(3*ζ*(-1 + (-4 + τP)*cs^2 + 5*(-1 + τP)*cs^4 + 2*r*(-1 + τP)*cs*cs_prime) + 4*η*(-1 + (-10 + τP)*cs^2 + (-23 + 5*τP)*cs^4 + 2*r*(-1 + τP)*cs*cs_prime - 12*r*cs^3*cs_prime)) - r*m*(3*ζ*(τε*(1 + 5*cs^2) + cs*(-((-2 - 8*π*r^2*ε + τP*(1 + 8*π*r^2*ε))*cs) - (-1 + τP)*(5 + 24*π*r^2*ε)*cs^3 - 2*r*(-1 + τP)*cs_prime) + 8*π*r^2*p*(-2 - (5 + 2*τP)*cs^2 + τε*(1 + 5*cs^2) + 2*r*(-1 + τP)*cs*cs_prime)) + 4*η*(τε*(1 + 5*cs^2) + 8*π*r^2*p*(-2 - (11 + 2*τP)*cs^2 - 3*cs^4 + τε*(1 + 5*cs^2) + 2*r*(-1 + τP)*cs*cs_prime) + cs*(-((-8 + τP - 8*π*r^2*ε + 8*π*r^2*τP*ε)*cs) + (35 + 48*π*r^2*ε - τP*(5 + 24*π*r^2*ε))*cs^3 - 2*r*(-1 + τP)*cs_prime + 24*r*cs^2*cs_prime))) - 2*r^2*(4*η*(16*π^2*r^4*p^2*(-1 + τε - cs^2) + cs^2*(-(τε*(1 + 2*π*r^2*ε)) + 2*π*r^2*τP*ε*(1 + 3*cs^2) - 3*cs*((1 + 4*π*r^2*ε)*cs + r*cs_prime)) + 2*π*r^2*p*(τε*(1 - 4*(1 + 2*π*r^2*ε)*cs^2) + cs*(2*(4 + τP + 4*π*r^2*ε)*cs + 3*cs^3 - 2*r*(-1 + τP)*cs_prime))) + 3*ζ*(16*π^2*r^4*p^2*(-1 + τε - cs^2) + cs^2*(-(τε*(1 + 2*π*r^2*ε)) + 2*π*r^2*ε*(τP - 3*cs^2 + 3*τP*cs^2)) + 2*π*r^2*p*(τε*(1 - 4*(1 + 2*π*r^2*ε)*cs^2) + 2*cs*((1 + τP + 4*π*r^2*ε)*cs - r*(-1 + τP)*cs_prime))))))/(9.0*exp(ν/2.)*r*(r - 2*m)^2*cs^2)

A2(m::Float64, p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime::Float64, cs_prime_prime::Float64, r::Float64, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64)::Float64 =(-4*L^2*π*(3*ζ + 4*η)*τQ*(p + ε)^2*(3*r*ζ*(4*π*r^2*p*(τP - 2*τε) - τε + (-1 + τP)*(-3 + 4*π*r^2*ε)*cs^2) + 4*r*η*(4*π*r^2*p*(τP - 2*τε) - τε + (-4*π*r^2*ε + τP*(-3 + 4*π*r^2*ε))*cs^2) + 3*m*ζ*(-5*cs^2 + τP*(1 + 5*cs^2)) + 4*m*η*(cs^2 + τP*(1 + 5*cs^2))))/(9.0*exp(ν/2.)*(r - 2*m))

A3(m::Float64, p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime::Float64, cs_prime_prime::Float64, r::Float64, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64)::Float64 =(4*L^2*π*r*(3*ζ + 4*η)^2*(-1 + τP)*τQ*(p + ε)^2*cs^2)/(9.0*exp(ν/2.))

A4(m::Float64, p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime::Float64, cs_prime_prime::Float64, r::Float64, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64)::Float64 =-0.018518518518518517*(L*(3*ζ + 4*η)*(p + ε)*(9*(r - 2*m)*τε*(2*m + 8*π*r^3*p - 2*(2*r - 5*m + 4*π*r^3*ε)*cs^2) + 18*(r - 2*m)*τQ*(m - 2*(r - 3*m + 2*π*r^3*ε)*cs^2 + 4*π*r^3*p*(1 + cs^2)) + 8*π*r^3*τε*(p + ε)*cs^2*(9*(r - 2*m) - 12*L^2*π*ζ*(3*ζ + 4*η)*(m + 4*π*r^3*p)*τQ*(p + ε) - 8*L^2*π*η*(3*ζ + 4*η)*τQ*(p + ε)*(2*m + 8*π*r^3*p - 6*(r - 2*m)*cs^2))))/(exp(ν)*r*(r - 2*m)^2*cs^2)

A5(m::Float64, p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime::Float64, cs_prime_prime::Float64, r::Float64, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64)::Float64 =(L*(3*ζ + 4*η)*(τQ + τε)*(p + ε))/(3.0*exp(ν))

A6(m::Float64, p::Float64, ε::Float64, ν::Float64, cs::Float64, cs_prime::Float64, cs_prime_prime::Float64, r::Float64, η::Float64, ζ::Float64, τε::Float64, τP::Float64, τQ::Float64, L::Float64)::Float64 =(-4*L^2*π*r^2*(3*ζ + 4*η)^2*τQ*τε*(p + ε)^2)/(9.0*exp((3*ν)/2.)*(r - 2*m))

